# Analyze connectivity better - find connected components based on adjacency
import numpy as np

positions = [(1, 2), (2, 1), (2,3), (3, 2), (3, 7), (4, 6), (4, 8), (5, 2), (5, 7), (5, 10), (6, 1), (6, 3), (6, 9), (6, 11), (7, 2), (7, 10)]

# Build adjacency - two points are connected if they're close enough
def manhattan_dist(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

# Find connected components
visited = set()
components = []

for i, p1 in enumerate(positions):
    if p1 in visited:
        continue

    # Start BFS/DFS from this point
    component = [p1]
    queue = [p1]

    while queue:
        current = queue.pop(0)
        if current in visited:
            continue
        visited.add(current)

        for p2 in positions:
            if p2 not in visited and manhattan_dist(current, p2) <= 3:  # Within Manhattan distance 3
                if p2 not in component:
                    component.append(p2)
                    queue.append(p2)

    component.sort()
    components.append(component)

print("Connected components:")
for i, comp in enumerate(components):
    print(f"\nComponent {i+1}:")
    for p in comp:
        print(f"  {p}")

